#[no_mangle]
pub unsafe extern "C" fn node_neighbors(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<2{return -1}let count=*v;let node=*v.add(1);if !(0..=64).contains(&count)||!(0..=63).contains(&node)||n!=2+2*count as usize{return -1}let mut seen=[false;64];let mut buf=[0u8;192];let mut used=0;for i in 0..count as usize{let a=*v.add(2+2*i);let b=*v.add(3+2*i);if !(0..=63).contains(&a)||!(0..=63).contains(&b){return -1}let x=if a==node{b}else if b==node{a}else{-1};if x>=0&&!seen[x as usize]{seen[x as usize]=true;if used>0{buf[used]=b',';used+=1}for byte in x.to_string().bytes(){buf[used]=byte;used+=1}}}if used>cap||(used>0&&out.is_null()){return -2}for i in 0..used{*out.add(i)=buf[i]}used as i64}
